import numpy as np
from scipy import stats

MAX_DRIVERS = 4

def design(feats):
    # Calculate t-statistics for all features
    t_stats = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'clinical':
            y0 = feats.x[feats.y==0, i]
            y1 = feats.x[feats.y==1, i]
            t_stat, _ = stats.ttest_ind(y0, y1, equal_var=False)
            t_stats.append(abs(t_stat))

    # Sort by t-statistic and get top features
    sorted_indices = np.argsort(t_stats)[::-1]
    top_features = [feats.ids[i] for i in sorted_indices[:MAX_DRIVERS]]

    # If no strong signals, return empty design
    if max(t_stats) <= 2.0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Return top features as drivers and columns
    return Design(
        drivers=tuple(top_features),
        columns=tuple(top_features),
        products=(),
        loadings={}
    )

